code.snippet:
body.t-chalkboard .bg-fx {
  background-image: radial-gradient(rgba(240,237,228,.05) 1px, transparent 1px);
  background-size: 7px 7px;
}
body.t-chalkboard .card, body.t-chalkboard .post, body.t-chalkboard .fact, body.t-chalkboard .contact-card,
body.t-chalkboard .tag, body.t-chalkboard .hero-badge, body.t-chalkboard .section-tag, body.t-chalkboard .btn-ghost {
  border-style: dashed;
}
body.t-chalkboard .hero h1 { color: #f0ede4; text-shadow: 0 0 2px rgba(240,237,228,.6), 2px 2px 0 rgba(240,237,228,.12); letter-spacing: 2px; }
body.t-chalkboard .tagline { color: var(--accent); }
body.t-chalkboard .tagline::before { content: "★ "; }
body.t-chalkboard .section-title { color: #f0ede4; text-shadow: 0 0 2px rgba(240,237,228,.5); }
body.t-chalkboard .section-title::after { content: ""; display: block; height: 6px; margin-top: 8px; background: repeating-linear-gradient(90deg, var(--border) 0 14px, transparent 14px 20px); opacity: .7; }
body.t-chalkboard .section-tag { background: transparent; color: var(--accent-2); }
body.t-chalkboard .card:hover { border-color: var(--accent); }
body.t-chalkboard .card.featured { border-color: var(--accent); }
body.t-chalkboard .card.featured::before { content: "★ 重点"; background: var(--accent); color: #22332d; font-weight: 700; }
body.t-chalkboard .btn-primary { background: var(--accent); color: #22332d; border: 2px dashed rgba(34,51,45,.7); font-weight: 700; }
body.t-chalkboard .btn-primary:hover { box-shadow: 0 0 22px rgba(255,209,102,.3); }
body.t-chalkboard .bar-track { border: 2px dashed var(--border); background: transparent; height: 12px; }
body.t-chalkboard .bar-fill { background: repeating-linear-gradient(-45deg, #f0ede4 0 5px, rgba(240,237,228,.35) 5px 9px); }
body.t-chalkboard .bar-row:first-child .bar-fill { background: repeating-linear-gradient(-45deg, var(--accent) 0 5px, rgba(255,209,102,.4) 5px 9px); }
body.t-chalkboard .bar-row:nth-child(2) .bar-fill { background: repeating-linear-gradient(-45deg, var(--accent-2) 0 5px, rgba(142,202,230,.4) 5px 9px); }
body.t-chalkboard .bar-row:nth-child(3) .bar-fill { background: repeating-linear-gradient(-45deg, #ff8fa3 0 5px, rgba(255,143,163,.4) 5px 9px); }
